import{_ as r,o as t,c as s,a2 as a}from"./chunks/framework.CqdVOxXJ.js";const n="/rakkii-cars-guide/screenshots/v2/d07-insurance-tab.png",g=JSON.parse('{"title":"Insurance jobs","description":"","frontmatter":{},"headers":[],"relativePath":"desk/insurance-jobs.md","filePath":"desk/insurance-jobs.md","lastUpdated":1794643263000}'),o={name:"desk/insurance-jobs.md"};function i(h,e,l,d,u,c){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="insurance-jobs" tabindex="-1">Insurance jobs <a class="header-anchor" href="#insurance-jobs" aria-label="Permalink to &quot;Insurance jobs&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Adds to:</strong> the <a href="/rakkii-cars-guide/desk/job/01-open-a-job">8 job steps</a></p><p>An insurance job has two payers:</p><ul><li>The <strong>insurer</strong> pays what the <strong>LOA</strong> (Letter of Authorization) covers, usually 15–45 days after you bill.</li><li>The <strong>customer</strong> pays their <strong>participation</strong> (deductible) and any extras <strong>before</strong> the car leaves.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Open the job (Insurance) → Quote → Waiting for LOA → Save the LOA → Mark authorized</span></span>
<span class="line"><span>→ Start work → QC → Bill insurer + Bill customer → Customer pays → Release</span></span>
<span class="line"><span>→ Insurer pays later → Mark as done</span></span></code></pre></div><h2 id="what-s-different-from-a-normal-job" tabindex="-1">What&#39;s different from a normal job <a class="header-anchor" href="#what-s-different-from-a-normal-job" aria-label="Permalink to &quot;What&#39;s different from a normal job&quot;">​</a></h2><h3 id="_1-open-the-job-as-insurance" tabindex="-1">1. Open the job as Insurance <a class="header-anchor" href="#_1-open-the-job-as-insurance" aria-label="Permalink to &quot;1. Open the job as Insurance&quot;">​</a></h3><p>On <strong>New job</strong>, set <strong>Job type</strong> to Insurance. Choose the <strong>Insurer</strong> and enter the <strong>Claim number</strong>, <strong>Policy number</strong> and <strong>Adjuster</strong>. The job gets an <strong>Insurance</strong> tab.</p><p>New insurer? Add it first in <strong>Workshop › Insurers</strong>.</p><h3 id="_2-quote-then-wait-for-the-loa" tabindex="-1">2. Quote, then wait for the LOA <a class="header-anchor" href="#_2-quote-then-wait-for-the-loa" aria-label="Permalink to &quot;2. Quote, then wait for the LOA&quot;">​</a></h3><ol><li>Add work lines. Set <strong>Who pays</strong> to <strong>Insurer</strong> for covered work and <strong>Customer</strong> for extras the customer asked for.</li><li><strong>Save quote</strong> and print the estimate for the adjuster.</li><li>Press <strong>Waiting for LOA</strong>.</li></ol><h3 id="_3-save-the-loa" tabindex="-1">3. Save the LOA <a class="header-anchor" href="#_3-save-the-loa" aria-label="Permalink to &quot;3. Save the LOA&quot;">​</a></h3><p>When the insurer&#39;s letter arrives:</p><ol><li>Open the <strong>Insurance</strong> tab, card <strong>Letter of authorization</strong>.</li><li>Enter the <strong>LOA number</strong>, <strong>LOA date</strong>, <strong>Authorized amount</strong>, <strong>Participation</strong>, any depreciation or betterment, and the insurer&#39;s expected pay date. Save.</li><li>Upload the letter as a PDF on the <strong>Files</strong> tab. Leave <strong>Visible in the customer portal</strong> off.</li></ol><p><img src="`+n+'" alt="Insurance tab"></p><h3 id="_4-mark-authorized-then-start-work" tabindex="-1">4. Mark authorized, then start work <a class="header-anchor" href="#_4-mark-authorized-then-start-work" aria-label="Permalink to &quot;4. Mark authorized, then start work&quot;">​</a></h3><p>Press <strong>Mark authorized</strong> (it needs the LOA number and amount), assign the technician and press <strong>Start work</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Don&#39;t start without an LOA</p><p><strong>Start work (cash / no LOA)</strong> exists for customers paying cash or written insurer approval. It asks for a reason, which is kept in the status log.</p></div><p><strong>Extra damage found?</strong> Get the insurer&#39;s approval, then add it under <strong>Supplements</strong> on the Insurance tab.</p><h3 id="_5-surrendered-parts" tabindex="-1">5. Surrendered parts <a class="header-anchor" href="#_5-surrendered-parts" aria-label="Permalink to &quot;5. Surrendered parts&quot;">​</a></h3><p>The technician logs the replaced parts going back to the insurer in <strong>Surrendered Parts</strong> (or ticks <strong>No parts to surrender</strong>). The release list reminds you.</p><h3 id="_6-bill-both-payers" tabindex="-1">6. Bill both payers <a class="header-anchor" href="#_6-bill-both-payers" aria-label="Permalink to &quot;6. Bill both payers&quot;">​</a></h3><p>On <strong>Pay › Invoices</strong>, press <strong>Bill insurer ₱…</strong> and <strong>Bill customer ₱…</strong>. The <strong>Summary</strong> shows <strong>Customer owes</strong> and <strong>Insurer owes</strong> separately.</p><h3 id="_7-collect-the-customer-s-share-and-release" tabindex="-1">7. Collect the customer&#39;s share and release <a class="header-anchor" href="#_7-collect-the-customer-s-share-and-release" aria-label="Permalink to &quot;7. Collect the customer&#39;s share and release&quot;">​</a></h3><p>Record the customer&#39;s payment (<strong>Who paid</strong>: Customer). The car is held until the customer has paid. It is <strong>not</strong> held for the insurer. Print the <strong>Release of Claim</strong> from the Release tab&#39;s <strong>Print ▾</strong> for the customer to sign.</p><h3 id="_8-when-the-insurer-pays" tabindex="-1">8. When the insurer pays <a class="header-anchor" href="#_8-when-the-insurer-pays" aria-label="Permalink to &quot;8. When the insurer pays&quot;">​</a></h3><p>Record it on the job with <strong>Who paid</strong>: Insurer, applied to the insurer invoice. Until then the job shows <strong>Released · not done</strong> and appears in <strong>Finance › Who owes us</strong>. Then <strong>Mark as done</strong>.</p><p>More detail: <a href="/rakkii-cars-guide/reference/06-lane-2-insurance-claims-and-loa">Insurance claims &amp; LOA (reference)</a>.</p>',28)])])}const b=r(o,[["render",i]]);export{g as __pageData,b as default};
